                || self.extension_type == ExtensionTypeSpec::Padding
                || self.extension_type == ExtensionTypeSpec::EncryptThenMac
                || self.extension_type == ExtensionTypeSpec::ExtendedMasterSecret
                || self.extension_type == ExtensionTypeSpec::CompressCertificate
                || self.extension_type == ExtensionTypeSpec::RecordSizeLimit
                || self.extension_type == ExtensionTypeSpec::SessionTicket
                || self.extension_type == ExtensionTypeSpec::SupportedEktCiphers
                || self.extension_type == ExtensionTypeSpec::PreSharedKey
