                || self.extension_type == ExtensionTypeSpec::CertificateAuthorities
                || self.extension_type == ExtensionTypeSpec::OidFilters
                || self.extension_type == ExtensionTypeSpec::PostHandshakeAuth
                || self.extension_type == ExtensionTypeSpec::SignatureAlgorithmsCert
                || self.extension_type == ExtensionTypeSpec::KeyShare
                || self.extension_type == ExtensionTypeSpec::ExternalIdHash
                || self.extension_type == ExtensionTypeSpec::ExternalSessionId
