            reveal(<TlsPlaintextFragmentFmt as SpecParser>::spec_parse);
            reveal(<TlsPlaintextFragment as DeepView>::deep_view);
            reveal(TlsPlaintextFragmentSpec::from_structural);
            let _ = ibuf.len();
